// components/MoneyReceipt/MoneyReceipt.jsx
import { jsPDF } from "jspdf";
import "./MoneyReceipt.css";

// Replace this with your actual base64 logo
const COMPANY_LOGO =
  "data:image/jpeg;base64,"; // Your actual base64 logo

// const COMPANY_LOGO = "";

export const generateMoneyReceiptPDF = (moneyReceipt, distDetails) => {
  const doc = new jsPDF();

  // Set page dimensions
  const pageWidth = doc.internal.pageSize.getWidth();
  const marginLeft = 10;
  let yPosition = -11;

  // Header Section with Logo only (removed PRAN-RFL GROUP text)
  try {
    if (COMPANY_LOGO) {
      // Center the logo where PRAN-RFL GROUP was
      const logoWidth = 60;
      const logoHeight = 35;
      const logoX = (pageWidth - logoWidth) / 2;
      doc.addImage(
        COMPANY_LOGO,
        "JPEG",
        logoX,
        yPosition,
        logoWidth,
        logoHeight
      );
      // yPosition += logoHeight + 4;
      yPosition += 25;
    }
  } catch (error) {
    console.log("Could not load logo, continuing without it");
    yPosition += 1;
  }

  doc.setFontSize(10);
  doc.setFont("helvetica", "normal");
  doc.text("CUSTOMER COPY", pageWidth / 2 + 50, yPosition - 6);

  // Company Address below logo
  doc.setFontSize(8);
  doc.setFont("helvetica", "normal");
  doc.text(
    "PRAN-RFL CENTER : 105 MIDDLE BADDA, GPO BOX: 83, DHAKA - 1212",
    pageWidth / 2,
    yPosition,
    { align: "center" }
  );
  yPosition += 4;
  doc.text(
    "TEL : 988834 Ext-150, Fax : 88-02-9880345",
    pageWidth / 2,
    yPosition,
    { align: "center" }
  );

  yPosition += 8;

  doc.setFontSize(9);
  doc.setFont("helvetica", "bold");
  doc.text("SL No :", marginLeft, yPosition);
  const slNo = moneyReceipt.SL || "";
  doc.setFont("helvetica", "normal");
  doc.text(slNo, marginLeft + 15, yPosition);

  // Money Receipt Title with underline
  doc.setFontSize(14);
  doc.setFont("helvetica", "bold");
  doc.text("Money Receipt", pageWidth / 2, yPosition, { align: "center" });
  // Underline
  doc.line(
    pageWidth / 2 - 25,
    yPosition + 1,
    pageWidth / 2 + 25,
    yPosition + 1
  );

  yPosition += 4;

  // Combined MR No and Received Section - Two column layout
  const boxWidth = pageWidth - marginLeft * 2;
  const columnWidth = boxWidth / 2;
  const leftColX = marginLeft;
  const rightColX = marginLeft + columnWidth;

  // Calculate content heights for both columns
  const distName =
    distDetails?.DIST_NAME || moneyReceipt.DISTNAME || "";
  const distNameLines = doc.splitTextToSize(distName, columnWidth - 10);
  const leftColumnHeight = 16 + (distNameLines.length - 1) * 4;

  const amount = moneyReceipt.AMOUNT ? moneyReceipt.AMOUNT : "0";
  const boxHeight = Math.max(20, leftColumnHeight); // Minimum height of 30

  // Draw main border box
  doc.setDrawColor(0, 0, 0);
  doc.rect(marginLeft, yPosition, boxWidth, boxHeight);

  // Left Column - Received section
  let leftY = yPosition + 4;
  // MR No
  doc.setFontSize(9);
  doc.setFont("helvetica", "bold");
  doc.text("MR No.", leftColX + 5, leftY);
  doc.setFont("helvetica", "normal");
  const mrNo = moneyReceipt.MRNO || "";
  doc.text(mrNo, leftColX + 25, leftY);
  leftY += 6;

  doc.setFont("helvetica", "bold");
  doc.text("Received with thanks", leftColX + 5, leftY);
  doc.setFont("helvetica", "normal");
  doc.text(`TK: ${amount.toLocaleString()}/-`, leftColX + 40, leftY);
  leftY += 6;

  doc.setFont("helvetica", "bold");
  doc.text("of", leftColX + 5, leftY);
  doc.setFont("helvetica", "normal");
  const addressParts = [moneyReceipt.ADDR1, moneyReceipt.ADDR2, moneyReceipt.ADDR3, moneyReceipt.ADDR4].filter(
    (part) => part && part !== "null" && part !== "undefined"
  );
  const address = addressParts.join(", ") || "Address not available";
  doc.text(address, leftColX + 10, leftY);

  // Right Column - MR No and Date
  let rightY = yPosition + 4;

  // Date
  doc.setFont("helvetica", "bold");
  doc.text("Date :", rightColX, rightY);
  doc.setFont("helvetica", "normal");
  const date = moneyReceipt.MRDATE || new Date().toLocaleDateString();
  doc.text(date, rightColX + 10, rightY);

  // On Account of
  doc.setFont("helvetica", "bold");
  doc.text("On Account of :", rightColX + 35, rightY);
  doc.setFont("helvetica", "normal");
  doc.text(moneyReceipt.ONACC || "", rightColX + 63, rightY);

  rightY += 6;

  // only from
  doc.setFont("helvetica", "bold");
  doc.text("only from :", rightColX, rightY);
  doc.setFont("helvetica", "normal");
  const distId = moneyReceipt.DISTID || "N/A";
  const distbutorName = moneyReceipt.DISTNAME || "N/A";
  doc.text(`${distId}-${distbutorName}`, rightColX + 20, rightY);

  yPosition += boxHeight + 4;

  // Payment Details Table
  const tableTop = yPosition;
  const colWidths = [22, 38, 40, 32, 22, 25];
  const headers = [
    "Pay Mode",
    "Bank",
    "Reference #",
    "Description",
    "Dated",
    "Amount",
  ];
  const rowHeight = 7; // Base row height

  // Table header with light gray background
  doc.setFillColor(245, 245, 245);
  doc.rect(marginLeft, tableTop, pageWidth - marginLeft * 2, rowHeight, "F");

  // Header borders
  doc.setDrawColor(200, 200, 200);
  doc.rect(marginLeft, tableTop, pageWidth - marginLeft * 2, rowHeight);

  let xPosition = marginLeft;
  doc.setFontSize(8);
  doc.setFont("helvetica", "bold");

  headers.forEach((header, index) => {
    doc.text(header, xPosition + 2, tableTop + 4.5);
    // Vertical lines
    if (index < headers.length - 1) {
      doc.line(
        xPosition + colWidths[index],
        tableTop,
        xPosition + colWidths[index],
        tableTop + rowHeight
      );
    }
    xPosition += colWidths[index];
  });

  yPosition += rowHeight;

  // Table data row - with multi-line support
  doc.setFont("helvetica", "normal");
  xPosition = marginLeft;

  const rowData = [
    moneyReceipt.PAYMODE || "",
    moneyReceipt.BANK || "",
    moneyReceipt.REFERENCES || "",
    moneyReceipt.DESCRIPTIONS || "",
    moneyReceipt.MRDATE || "",
    moneyReceipt.AMOUNT ? moneyReceipt.AMOUNT.toLocaleString() : "0",
  ];

  // Calculate maximum number of lines needed for any cell
  let maxLines = 1;
  const cellLines = [];

  rowData.forEach((data, index) => {
    const text = data.toString();
    // Split text to fit column width (with 2px padding on each side)
    const lines = doc.splitTextToSize(text, colWidths[index] - 4);
    cellLines.push(lines);
    maxLines = Math.max(maxLines, lines.length);
  });

  // Calculate dynamic row height based on content
  const dynamicRowHeight = maxLines * 6; // 4px per line

  // Data row background - dynamic height
  doc.setFillColor(255, 255, 255);
  doc.rect(
    marginLeft,
    yPosition,
    pageWidth - marginLeft * 2,
    dynamicRowHeight,
    "F"
  );
  doc.rect(marginLeft, yPosition, pageWidth - marginLeft * 2, dynamicRowHeight);

  // Draw cell content with line breaks
  cellLines.forEach((lines, index) => {
    let textY = yPosition + 4.5; // Start position for text

    lines.forEach((line) => {
      doc.text(line, xPosition + 4, textY);
      textY += 4; // Move down for next line (4px line height)
    });

    // Vertical lines
    if (index < headers.length - 1) {
      doc.line(
        xPosition + colWidths[index],
        yPosition,
        xPosition + colWidths[index],
        yPosition + dynamicRowHeight
      );
    }
    xPosition += colWidths[index];
  });

  yPosition += dynamicRowHeight + 4; // Add small gap after table

  // yPosition += 12;

  // Amount in words section
  doc.setFont("helvetica", "bold");
  doc.text(`In words (${moneyReceipt.CURRENCY_CODE || "BDT"}) :`, marginLeft, yPosition);
  doc.setFont("helvetica", "normal");
  doc.setFontSize(9);

  const amountInWords = convertNumberToWords(amount);
  // Split long text into multiple lines
  const wordsLines = doc.splitTextToSize(
    amountInWords,
    pageWidth - marginLeft - 50
  );
  doc.text(wordsLines, marginLeft + 25, yPosition);

  yPosition += 4;

  doc.setFont("helvetica", "bold");
  doc.text("Grand Total :", marginLeft + 135, yPosition - 4);
  doc.setFont("helvetica", "normal");
  doc.text(amount.toLocaleString(), marginLeft + 155, yPosition - 4);

  // yPosition += wordsLines.length * 4 + 8;

  // Horizontal line
  //   doc.line(marginLeft, yPosition, pageWidth - marginLeft, yPosition);

  yPosition += 2;

  // Two column footer section
  const footerLeftColX = marginLeft;
  const footerRightColX = pageWidth / 2 + 10;

  // Left column - Received By section
  doc.setFontSize(10);
  doc.setFont("helvetica", "bold");
  doc.text("Received By (" + (moneyReceipt.USERNAME || "") + ")", footerLeftColX, yPosition);

  yPosition += 5;
  doc.setFont("helvetica", "normal");
  doc.setFontSize(7);
  const noteText =
    "N. B : Cheque, DD and Pay Orders are Subject to Realization";
  doc.text(noteText, footerLeftColX, yPosition);

  // Right column - Details section

  // yPosition += 4;

  doc.setFont("helvetica", "bold");
  doc.text("Printed on :", footerRightColX, yPosition - 6);
  doc.setFont("helvetica", "normal");
  doc.text(new Date().toLocaleString(), footerRightColX + 25, yPosition - 6);

  // yPosition += 5;
  // doc.setFont("helvetica", "bold");
  // doc.text("User name :", footerRightColX, yPosition - 6);
  // doc.setFont("helvetica", "normal");
  // doc.text(moneyReceipt.USERNAME || "", footerRightColX + 25, yPosition - 6);

  // Save the PDF
  const fileName = `Money_Receipt_${moneyReceipt.MRNO || "receipt"}.pdf`;
  // doc.save(fileName);
  const pdfBlob = doc.output('blob');
  const pdfUrl = URL.createObjectURL(pdfBlob);
  window.open(pdfUrl, '_blank');

  return fileName;
};

// Enhanced number to words conversion
const convertNumberToWords = (amount) => {
  if (amount === 0) return "Zero Taka Only";

  const ones = [
    "",
    "One",
    "Two",
    "Three",
    "Four",
    "Five",
    "Six",
    "Seven",
    "Eight",
    "Nine",
  ];
  const teens = [
    "Ten",
    "Eleven",
    "Twelve",
    "Thirteen",
    "Fourteen",
    "Fifteen",
    "Sixteen",
    "Seventeen",
    "Eighteen",
    "Nineteen",
  ];
  const tens = [
    "",
    "",
    "Twenty",
    "Thirty",
    "Forty",
    "Fifty",
    "Sixty",
    "Seventy",
    "Eighty",
    "Ninety",
  ];

  let words = "";
  let mainAmount = Math.floor(amount);

  // Crore
  if (mainAmount >= 10000000) {
    words +=
      convertNumberToWords(Math.floor(mainAmount / 10000000)) + " Crore ";
    mainAmount %= 10000000;
  }

  // Lakh
  if (mainAmount >= 100000) {
    words += convertNumberToWords(Math.floor(mainAmount / 100000)) + " Lakh ";
    mainAmount %= 100000;
  }

  // Thousand
  if (mainAmount >= 1000) {
    words += convertNumberToWords(Math.floor(mainAmount / 1000)) + " Thousand ";
    mainAmount %= 1000;
  }

  // Hundred
  if (mainAmount >= 100) {
    words += convertNumberToWords(Math.floor(mainAmount / 100)) + " Hundred ";
    mainAmount %= 100;
  }

  // Tens and Ones
  if (mainAmount > 0) {
    if (words !== "") words += "and ";

    if (mainAmount < 10) {
      words += ones[mainAmount];
    } else if (mainAmount < 20) {
      words += teens[mainAmount - 10];
    } else {
      words += tens[Math.floor(mainAmount / 10)];
      if (mainAmount % 10 > 0) {
        words += " " + ones[mainAmount % 10];
      }
    }
  }

  // return words + ' Taka Only';
  return words + "";
};
